import React from "react";
import styled from "styled-components";
import ClassPic1 from "../../assets/images/gallery/ClassCampusGallery/ClassPic1.jpeg";
import ClassPic2 from "../../assets/images/gallery/ClassCampusGallery/ClassPic2.jpeg";
import ClassPic3 from "../../assets/images/gallery/ClassCampusGallery/ClassPic3.jpeg";
import ClassPic4 from "../../assets/images/gallery/ClassCampusGallery/ClassPic4.jpeg";
import ClassPic5 from "../../assets/images/gallery/ClassCampusGallery/ClassPic5.jpeg";

const IMAGES = [
  { src: ClassPic1, label: "Class Campus 1" },
  { src: ClassPic2, label: "Class Campus 2" },
  { src: ClassPic3, label: "Class Campus 3" },
  { src: ClassPic4, label: "Class Campus 4" },
  { src: ClassPic5, label: "Class Campus 5" }
];

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 2rem;
  margin: 2.5rem 0;
`;

const Card = styled.div`
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 2px 12px #0002;
  padding: 1.2rem;
  text-align: center;
`;

const Pic = styled.img`
  width: 100%;
  max-width: 320px;
  height: 220px;
  border-radius: 10px;
  object-fit: cover;
  margin-bottom: 1rem;
`;

export default function ClassCampusGallery() {
  return (
    <>
      <h2 style={{textAlign: "center", margin: "2rem 0 0.5rem 0"}}>Teachers’ Class Campus Photos</h2>
      <Grid>
        {IMAGES.map((img, i) => (
          <Card key={i}>
            <Pic src={img.src} alt={img.label} />
            <div>{img.label}</div>
          </Card>
        ))}
      </Grid>
    </>
  );
}