import React from "react";
import styled from "styled-components";
import Event1 from "../../assets/images/gallery/EventsGallery/Event1.jpeg";
import Event2 from "../../assets/images/gallery/EventsGallery/Event2.jpeg";
import Event3 from "../../assets/images/gallery/EventsGallery/Event3.jpeg";
import Event4 from "../../assets/images/gallery/EventsGallery/Event4.jpeg";
import Event5 from "../../assets/images/gallery/EventsGallery/Event5.jpeg";

const IMAGES = [
  { src: Event1, label: "Event 1"},
  { src: Event2, label: "Event 2"},
  { src: Event3, label: "Event 3"},
  { src: Event4, label: "Event 4"},
  { src: Event5, label: "Event 5"}
];

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 2rem;
  margin: 2.5rem 0;
`;

const Card = styled.div`
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 2px 12px #0002;
  padding: 1.2rem;
  text-align: center;
`;

const Pic = styled.img`
  width: 100%;
  max-width: 320px;
  height: 220px;
  border-radius: 10px;
  object-fit: cover;
  margin-bottom: 1rem;
`;

export default function EventsGallery() {
  return (
    <>
      <h2 style={{textAlign: "center", margin: "2rem 0 0.5rem 0"}}>Event Day Pics</h2>
      <Grid>
        {IMAGES.map((img, i) => (
          <Card key={i}>
            <Pic src={img.src} alt={img.label} />
            <div>{img.label}</div>
          </Card>
        ))}
      </Grid>
    </>
  );
}