import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import "./WhatTeachersMean.css";

const videoSrc = require("../assets/videos/mov_bbb1.mp4");

const messages = [
  "Teachers inspire us to dream, learn, and grow.",
  "Their encouragement opens doors to new possibilities.",
  "Thank you for believing in us, always!",
];

export default function WhatTeachersMean() {
  const [showModal, setShowModal] = useState(false);

  return (
    <div className="teachers-meaning-bg" onClick={() => setShowModal(true)}>
      {/* Video Background */}
      <video
        className="teachers-meaning-video-bg"
        src={videoSrc}
        autoPlay
        loop
        muted
        playsInline
      />

      {/* Overlay for readability */}
      <div className="teachers-meaning-overlay" />

      <motion.div
        className="teachers-meaning-content"
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1 }}
      >
        <motion.h1
          className="teachers-meaning-title"
          initial={{ opacity: 0, y: -30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
        >
          What Our Teachers Mean to Us
        </motion.h1>
        <motion.p
          className="teachers-meaning-desc"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.3 }}
        >
          A heartfelt tribute from students expressing their gratitude, admiration, and love for our amazing teachers.
        </motion.p>

        {/* Extra heartfelt messages */}
        <div className="teachers-messages">
          {messages.map((msg, i) => (
            <motion.div
              key={i}
              className="teachers-message"
              initial={{ opacity: 0, x: -30 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.7, delay: 0.5 + i * 0.2 }}
            >
              <span role="img" aria-label="heart">💖</span> {msg}
            </motion.div>
          ))}
        </div>
        <span className="teachers-popup-hint">Click anywhere to watch the tribute video!</span>
      </motion.div>

      {/* Animated floating hearts */}
      <motion.div
        className="floating-hearts"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 2, delay: 1 }}
      >
        {[...Array(6)].map((_, i) => (
          <span
            key={i}
            className={`heart heart${i + 1}`}
            role="img"
            aria-label="heart"
          >💗</span>
        ))}
      </motion.div>

      {/* Modal popup for video */}
      <AnimatePresence>
        {showModal && (
          <motion.div
            className="teachers-modal-bg"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setShowModal(false)}
          >
            <motion.div
              className="teachers-modal-video-wrap"
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.8, opacity: 0 }}
              onClick={e => e.stopPropagation()} // Prevent closing when clicking video
            >
              <video
                src={videoSrc}
                controls
                autoPlay
                className="teachers-modal-video"
                poster="/assets/images/teachers-poster.jpg"
              />
              <button className="teachers-modal-close" onClick={() => setShowModal(false)}>
                ×
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}