import React from "react";
import styled from "styled-components";
import Chart1 from "../../assets/images/gallery/ChartsGallery/Chart1.jpeg";
import Chart2 from "../../assets/images/gallery/ChartsGallery/Chart2.jpeg";
import Chart3 from "../../assets/images/gallery/ChartsGallery/Chart3.jpeg";
import Chart4 from "../../assets/images/gallery/ChartsGallery/Chart4.jpeg";
import Chart5 from "../../assets/images/gallery/ChartsGallery/Chart5.jpeg";

const IMAGES = [
  { src: Chart1, label: "Chart 1" },
  { src: Chart2, label: "Chart 2" },
  { src: Chart3, label: "Chart 3" },
  { src: Chart4, label: "Chart 4" },
  { src: Chart5, label: "Chart 5" }
];

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 2rem;
  margin: 2.5rem 0;
`;

const Card = styled.div`
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 2px 12px #0002;
  padding: 1.2rem;
  text-align: center;
`;

const Pic = styled.img`
  width: 100%;
  max-width: 320px;
  height: 220px;
  border-radius: 10px;
  object-fit: cover;
  margin-bottom: 1rem;
`;

export default function ChartsGallery() {
  return (
    <>
      <h2 style={{textAlign: "center", margin: "2rem 0 0.5rem 0"}}>Chart Making</h2>
      <Grid>
        {IMAGES.map((img, i) => (
          <Card key={i}>
            <Pic src={img.src} alt={img.label} />
            <div>{img.label}</div>
          </Card>
        ))}
      </Grid>
    </>
  );
}