import React from "react";
import styled from "styled-components";

// You need to import images statically when using src folder in React!
import Game1 from "../../assets/images/gallery/GamesGallery/Game1.jpg";
import Game2 from "../../assets/images/gallery/GamesGallery/Game2.jpg";
import Game3 from "../../assets/images/gallery/GamesGallery/Game3.jpg";
import Game4 from "../../assets/images/gallery/GamesGallery/Game4.jpg";
import Game5 from "../../assets/images/gallery/GamesGallery/Game5.jpg";

const IMAGES = [
  { src: Game1, label: "Game 1"},
  { src: Game2, label: "Game 2"},
  { src: Game3, label: "Game 3"},
  { src: Game4, label: "Game 4"},
  { src: Game5, label: "Game 5"}
];

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 2rem;
  margin: 2.5rem 0;
`;
const Card = styled.div`
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 2px 12px #0002;
  padding: 1.2rem;
  text-align: center;
`;
const Pic = styled.img`
  width: 100%;
  max-width: 320px;
  height: 220px;
  border-radius: 10px;
  object-fit: cover;
  margin-bottom: 1rem;
`;

export default function GamesGallery() {
  return (
    <>
      <h2 style={{textAlign: "center", margin: "2rem 0 0.5rem 0"}}>Games Gallery</h2>
      <Grid>
        {IMAGES.map((img, i) => (
          <Card key={i}>
            <Pic src={img.src} alt={img.label} />
            <div>{img.label}</div>
          </Card>
        ))}
      </Grid>
    </>
  );
}